-- The 79 policies as live on 2026-11-27 (each table reduced to the columns its policies use),
-- on plain Postgres with Supabase's roles, auth.uid() and internal.is_current_user_admin().
do $$ begin
  if not exists (select from pg_roles where rolname = 'anon') then create role anon nologin; end if;
  if not exists (select from pg_roles where rolname = 'authenticated') then create role authenticated nologin; end if;
end $$;
create schema auth;
create function auth.uid() returns uuid language sql stable
  as $$ select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $$;
create function auth.role() returns text language sql stable as $$ select current_user::text $$;
grant usage on schema auth, public to anon, authenticated;
create type public.user_role as enum ('admin', 'user');
create type public.question_status as enum ('draft', 'pending_review', 'published', 'rejected');
create table public.users (id uuid primary key, role public.user_role not null default 'user');
alter table public.users enable row level security;
create policy users_select on public.users for select to public using (id = (select auth.uid()));
grant select on public.users to authenticated;
create schema internal;
grant usage on schema internal to authenticated;
create function internal.is_current_user_admin() returns boolean language plpgsql security definer
  set search_path to 'public'
  as $$ begin return exists (select 1 from users where id = auth.uid() and role = 'admin'); end $$;
revoke execute on function internal.is_current_user_admin() from public;
grant execute on function internal.is_current_user_admin() to authenticated;
create table public.quiz_attempts (question_id uuid, user_id uuid);
grant select on public.quiz_attempts to authenticated;
insert into public.users values ('00000000-0000-0000-0000-0000000000a1', 'admin'), ('00000000-0000-0000-0000-0000000000b1', 'user');

