create policy "Question options read access" on public.question_options for select to authenticated using (((EXISTS ( SELECT 1 FROM users WHERE ((users.id = ( SELECT auth.uid() AS uid)) AND (users.role = 'admin'::user_role)))) OR ((( SELECT auth.role() AS role) = 'authenticated'::text) AND (EXISTS ( SELECT 1 FROM questions WHERE ((questions.id = question_options.question_id) AND (questions.status = 'published'::question_status))))) OR (EXISTS ( SELECT 1 FROM quiz_attempts WHERE ((quiz_attempts.question_id = question_options.question_id) AND (quiz_attempts.user_id = ( SELECT auth.uid() AS uid)))))));
create policy "question_sets_delete_admin" on public.question_sets for delete to authenticated using ((EXISTS ( SELECT 1 FROM users WHERE ((users.id = ( SELECT auth.uid() AS uid)) AND (users.role = 'admin'::user_role)))));
create policy "Questions read access" on public.questions for select to authenticated using (((status = 'published'::question_status) OR (created_by = ( SELECT auth.uid() AS uid)) OR (reviewer_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1 FROM users WHERE ((users.id = ( SELECT auth.uid() AS uid)) AND (users.role = 'admin'::user_role)))) OR (EXISTS ( SELECT 1 FROM quiz_attempts WHERE ((quiz_attempts.question_id = questions.id) AND (quiz_attempts.user_id = ( SELECT auth.uid() AS uid)))))));
